# Original photo-led Latvian observance pages. Source metadata stays attached.
def occasion_page(article, all)
 photo=article.fetch('photo');type=article['type'];status=article['dayOff'] ? 'Svētku brīvdiena' : type=='commemoration' ? 'Atceres diena' : type=='astronomy' ? 'Astronomisks notikums' : 'Atzīmējamā diena'
 dates=article.fetch('dates',[]);cards=(2027..2030).map do |year|
  rows=dates.select{|r|r['date'].start_with?(year.to_s)}
  text=rows.empty? ? '<p class="occasion-pending">Norises datums šajā gadā nav apstiprināts.</p>' : rows.map{|r|d=Date.parse(r['date']);'<div><time datetime="'+h(r['date'])+'">'+h("#{d.day}. #{MONTHS[d.month-1]}")+'</time><span>'+h(%w[pirmdiena otrdiena trešdiena ceturtdiena piektdiena sestdiena svētdiena][d.cwday-1])+'</span><small>'+h(r['title'])+'</small></div>'}.join
  '<article><strong>'+year.to_s+'</strong>'+text+'</article>'
 end.join
 source_links=article.fetch('sourceUrls',[]).uniq.map{|url|'<li>'+a(url,URI.parse(url).host.to_s+' — pirmavots')+'</li>'}.join
 notes=article.fetch('factNotes',[]).map{|n|'<section><h2>'+h(n['section'])+'</h2><p>'+h(n['text'])+'</p></section>'}.join
 notes=article['bodyHtml'] if notes.empty?
 related=all.reject{|x|x['slug']==article['slug']}.sort_by{|x|[x['type']==type ? 0:1,x['title']]}.first(4).map{|r|p=r.fetch('photo');'<a href="/svetki-un-tradicijas/'+h(r['slug'])+'/"><img src="'+h(p['src'])+'" alt="'+h(p['alt'])+'" loading="lazy" width="480" height="300"><span>'+h(r['title'])+' <b aria-hidden="true">→</b></span></a>'}.join
 '<article class="occasion-story"><section class="occasion-opening"><div class="occasion-opening-copy"><span class="occasion-status">'+ui_icon(type=='astronomy' ? 'sun':'gift')+h(status)+'</span><h2>'+h(article.fetch('dateRule',{}).fetch('label',article['title']))+'</h2><p>'+h(article['intro']||article['description'])+'</p><div class="occasion-actions">'+a('#datumi','Skatīt datumus','button primary')+a('/atvalinajuma-planotajs/','Pievienot saviem plāniem','button')+'</div></div><figure><img src="'+h(photo['src'])+'" srcset="'+h(photo['srcset'])+'" sizes="(max-width: 800px) 95vw, 650px" alt="'+h(photo['alt'])+'" width="'+photo['width'].to_s+'" height="'+photo['height'].to_s+'" fetchpriority="high"><figcaption>'+h(photo['caption'])+' <span>'+h(photo['author'])+' · '+a(photo['licenseUrl'],photo['license'])+' · '+a(photo['sourceUrl'],'Avota fotogrāfija')+'</span></figcaption></figure></section><section class="occasion-dates" id="datumi"><div class="section-heading"><div><span class="eyebrow">PLĀNO LAIKUS</span><h2>Datumi 2027.–2030. gadā</h2></div><span>'+h(status)+'</span></div><div class="occasion-year-cards">'+cards+'</div></section><div class="occasion-reading"><div>'+notes+'</div><aside><span class="eyebrow">DATUMS UN NOZĪME</span><h2>Kas jāņem vērā?</h2><p>'+(article['dayOff'] ? 'Svētku dienas statuss ir noteikts Latvijas likumā. Darba dienu pārcelšana un aizstājoša brīvdiena jāvērtē pēc konkrētā noteikuma.' : 'Atzīmējama vai atceres diena pati par sevi nav vispārēja svētku brīvdiena.')+'</p><h3>Avoti</h3><ul>'+source_links+'</ul>'+a('/avoti-un-metodika/','Kā pārbaudām kalendāru →')+'</aside></div><section class="occasion-related"><div class="section-heading"><h2>Vēl dienas, ko iepazīt</h2>'+a('/svetki-un-tradicijas/','Visi svētki un tradīcijas →')+'</div><div>'+related+'</div></section></article>'
end
